<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class UserController extends Controller {private function admin(Request $r):void{abort_unless($r->user()->isAdmin(),403);}public function index(Request $r){$this->admin($r);$users=User::latest()->get();return view('users.index',compact('users'));}public function edit(Request $r,$id){$this->admin($r);$user=User::findOrFail($id);return view('users.edit',compact('user'));}public function update(Request $r,$id){$this->admin($r);$user=User::findOrFail($id);$data=$r->validate(['name'=>'required|string|max:255','email'=>['required','email','max:255','unique:users,email,'.$user->id],'role'=>'required|in:admin,manager,staff','is_active'=>'required|boolean','password'=>'nullable|string|min:8|confirmed']);$payload=['name'=>$data['name'],'email'=>$data['email'],'role'=>$data['role'],'is_active'=>$data['is_active']];if(!empty($data['password']))$payload['password']=Hash::make($data['password']);$user->update($payload);return redirect()->route('users.index')->with('success','User updated successfully.');}}
